eLq.text:
// When mother needs a new path:
call 'door scrape' ()         ← fills path //dontsave//
set [path step] = 1

// Each time she successfully passes through a door:
set [mid door index] = path //dontsave//[path step]
set [target x] = Door x's[mid door index]
set [target y] = Door y's[mid door index]
change [path step] by 1

// Update my room after passing through:
set [my room] = Door to's[mid door index]

